// QueryLines queries the lines edge of a RollingStock.
func (c *RollingStockClient) QueryLines(_m *RollingStock) *LineQuery {
	query := (&LineClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(rollingstock.Table, rollingstock.FieldID, id),
			sqlgraph.To(line.Table, line.FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, rollingstock.LinesTable, rollingstock.LinesColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

